import { RadarChartAdapter } from '@dreadnought/react/unstyled';
const metrics = ['quality','coverage','latency'].map(id => ({id,label:id,domain:[0,100] as const}));
const series = [{id:'a',label:'A',values:{quality:80,coverage:70,latency:60}}];
export function Example() { return <RadarChartAdapter label="Сравнение" metrics={metrics} series={series} width={400} height={320} />; }

import { RadarChartAdapter } from '@dreadnought/react/unstyled';
const metrics = ['x','y','z'].map(id => ({id,label:id,domain:[0,100] as const}));
const series = [{id:'a',label:'A',values:{x:80,y:60,z:40}}];
export function Example() { return <RadarChartAdapter label="Сравнение" metrics={metrics} series={series}><RadarChartAdapter.Legend /><RadarChartAdapter.Plot tooltipContent={({defaultContent}) => <div>{defaultContent}</div>}>{({defaultContent}) => defaultContent}</RadarChartAdapter.Plot><RadarChartAdapter.Table /></RadarChartAdapter>; }
